/* OpenStreetMap discovery: names/locations only, never a clinical destination recommendation. */
let nearbyBusy=false,nearbyResults=[],nearbyError='';
const beforeNearbyRender=render;
render=function(){beforeNearbyRender();if(page!=='Hospitals')return;const box=document.createElement('section');box.className='card';box.style.marginTop='20px';box.innerHTML=`<h2>Hospitals near you</h2><p>Find mapped hospitals within 25 km using your current location. Location is requested only when you choose the button. Your coordinates are sent to the OpenStreetMap Overpass service to search nearby facilities.</p><button class="btn" onclick="findNearbyHospitals()" ${nearbyBusy?'disabled':''}>${nearbyBusy?'Finding nearby hospitals…':'Use my location & find hospitals'}</button><p class="sub">Straight-line distances, not travel time. Map records may be incomplete or outdated. Confirm emergency services, capacity and destination suitability with a dispatcher. In an emergency call local emergency services.</p><p role="status">${esc(nearbyError)}</p>${nearbyResults.map(h=>`<div class="queue"><h3>${esc(h.name)}</h3><p>${h.distance.toFixed(1)} km away · Emergency availability: unknown</p><p class="sub">${esc(h.address)} · OpenStreetMap data</p><a href="https://www.openstreetmap.org/?mlat=${h.lat}&mlon=${h.lon}#map=16/${h.lat}/${h.lon}" target="_blank" rel="noopener">View location ↗</a></div>`).join('')}<p class="sub">Hospital map data © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap contributors</a>. Discovery does not verify that a facility is open.</p>`;$('#content').append(box)};
async function findNearbyHospitals(){if(nearbyBusy)return;if(!navigator.geolocation){nearbyError='Geolocation is unavailable. Use a browser with location support and HTTPS.';return render()}nearbyBusy=true;nearbyError='';render();const searchingTenant=tenantId;
try{const position=await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,{enableHighAccuracy:false,timeout:15000,maximumAge:60000}));const lat=position.coords.latitude,lon=position.coords.longitude;if(!Number.isFinite(lat)||!Number.isFinite(lon))throw Error('Invalid coordinates');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),30000);let result;
try{const query=`[out:json][timeout:20];nwr["amenity"="hospital"](around:25000,${lat},${lon});out center tags;`;const response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:query}),signal:controller.signal});if(!response.ok)throw Error('Hospital directory is temporarily unavailable. Try again later.');result=await response.json()}finally{clearTimeout(timer)}
if(searchingTenant!==tenantId)return;const seen=new Set();nearbyResults=(result.elements||[]).map(h=>({id:`osm-${h.type}-${h.id}`,name:h.tags?.name||'Unnamed mapped hospital',lat:h.lat??h.center?.lat,lon:h.lon??h.center?.lon,address:[h.tags?.['addr:street'],h.tags?.['addr:city']].filter(Boolean).join(', ')})).filter(h=>Number.isFinite(h.lat)&&Number.isFinite(h.lon)).map(h=>({...h,distance:distance({lat,lon},h)})).filter(h=>{const key=h.name.toLowerCase()+Math.round(h.lat*1000)+Math.round(h.lon*1000);if(seen.has(key))return false;seen.add(key);return h.distance<=25}).sort((a,b)=>a.distance-b.distance).slice(0,30);
for(const h of nearbyResults){if(!hospitals.some(x=>x.osmId===h.id))hospitals.push({name:h.name,status:'Unknown',capacity:0,updated:new Date().toISOString(),osmId:h.id,lat:h.lat,lon:h.lon})}nearbyError=nearbyResults.length?`Found ${nearbyResults.length} mapped hospitals. Added to this tenant’s session directory; reported beds have not been verified.`:'No mapped hospitals found within 25 km. This does not mean no hospitals exist nearby.';log('Nearby hospital discovery completed; location not logged');
}catch(e){nearbyError=e.code===1?'Location permission was denied. You can still use the existing hospital directory.':e.name==='AbortError'?'The hospital directory timed out. Try again later.':e.message||'Unable to obtain your location.'}finally{nearbyBusy=false;render()}}
const beforeNearbySwitch=switchTenant;switchTenant=function(id){if(id!==tenantId){nearbyResults=[];nearbyError=''}beforeNearbySwitch(id)};render();
let checkedLocationPermission=false;
const nearbyPermissionRender=render;render=function(){nearbyPermissionRender();if(page==='Hospitals'&&!checkedLocationPermission&&navigator.permissions){checkedLocationPermission=true;navigator.permissions.query({name:'geolocation'}).then(p=>{if(p.state==='granted'&&page==='Hospitals'&&!nearbyResults.length)findNearbyHospitals()}).catch(()=>{})}};
